import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/accessory/commands.md","filePath":"en/modules/accessory/commands.md","lastUpdated":0}`),a={name:`en/modules/accessory/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to “Commands and Permissions”">​</a></h1><p>EmakiAccessory registers its commands at runtime instead of declaring a <code>commands:</code> section in <code>paper-plugin.yml</code>.</p><p>The main command is <code>/emakiaccessory</code>, with the aliases <code>/eaccessory</code> and <code>/eacc</code>. Running it without arguments, or with an unrecognised subcommand, prints the help text.</p><h2 id="subcommands" tabindex="-1">Subcommands <a class="header-anchor" href="#subcommands" aria-label="Permalink to “Subcommands”">​</a></h2><table tabindex="0"><thead><tr><th>Usage</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/eacc</code></td><td>none</td><td>Print help.</td></tr><tr><td><code>/eacc open [page]</code></td><td><code>emakiaccessory.use</code></td><td>Open your own accessory panel; omitting the page opens the currently enabled one.</td></tr><tr><td><code>/eacc list</code></td><td><code>emakiaccessory.use</code></td><td>List the slots and occupancy of the currently enabled page.</td></tr><tr><td><code>/eacc pages</code></td><td><code>emakiaccessory.use</code></td><td>List every accessory page, the enabled one, and per-page occupancy.</td></tr><tr><td><code>/eacc retrieve &lt;page&gt;</code></td><td><code>emakiaccessory.use</code></td><td>Retrieve accessories from orphan slots on that page.</td></tr><tr><td><code>/eacc reload</code></td><td><code>emakiaccessory.reload</code></td><td>Reload configuration, parts, pages, and sets.</td></tr><tr><td><code>/eacc debug</code></td><td><code>emakiaccessory.debug</code></td><td>Debug switches.</td></tr><tr><td><code>/eacc admin &lt;...&gt;</code></td><td><code>emakiaccessory.admin</code></td><td>Administrative commands, see below.</td></tr></tbody></table><p><code>open</code>, <code>list</code>, <code>pages</code>, and <code>retrieve</code> are player-only. While a player&#39;s data is still loading, they report that instead of returning an empty result.</p><h2 id="administrative-commands" tabindex="-1">Administrative Commands <a class="header-anchor" href="#administrative-commands" aria-label="Permalink to “Administrative Commands”">​</a></h2><table tabindex="0"><thead><tr><th>Usage</th><th>Extra permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/eacc admin view &lt;player&gt;</code></td><td>none</td><td>View accessories (read-only).</td></tr><tr><td><code>/eacc admin edit &lt;player&gt;</code></td><td><code>emakiaccessory.admin.edit</code></td><td>Edit accessories, <strong>online players only</strong>.</td></tr><tr><td><code>/eacc admin clear &lt;player&gt;</code></td><td>none</td><td>Clear accessories. <strong>Cannot be undone</strong> and is written to the log.</td></tr><tr><td><code>/eacc admin save</code></td><td>none</td><td>Flush all accessory data immediately.</td></tr></tbody></table><p>All four require <code>emakiaccessory.admin</code> first. <code>edit</code> additionally requires <code>emakiaccessory.admin.edit</code>, splitting &quot;may look&quot; from &quot;may change&quot; so support staff can be given view access without edit access.</p><p><code>view</code> supports offline players: when the target is not cached, the data is loaded asynchronously and opened in a read-only window. <code>edit</code> requires an online target because a writable window needs a live data session.</p><h2 id="pages-and-retrieval" tabindex="-1">Pages and retrieval <a class="header-anchor" href="#pages-and-retrieval" aria-label="Permalink to “Pages and retrieval”">​</a></h2><p>With the multi-page model, command scope matters:</p><table tabindex="0"><thead><tr><th>Command</th><th>Scope</th></tr></thead><tbody><tr><td><code>open [page]</code></td><td>Opens that page&#39;s GUI; it will not open without the page permission</td></tr><tr><td><code>list</code></td><td>Lists slots on the <strong>currently enabled page</strong> only</td></tr><tr><td><code>pages</code></td><td>Lists all pages and marks the enabled and unavailable ones</td></tr><tr><td><code>retrieve &lt;page&gt;</code></td><td>Retrieves orphan-slot accessories on <strong>that page</strong> only</td></tr></tbody></table><p>An orphan slot is one that still holds data on a page whose <code>parts</code> no longer declares it. Retrieval is one-way: once taken out, an item cannot be put back into an orphan slot. <code>retrieve</code> needs the player&#39;s write lease and reports a busy state when the lease is held elsewhere.</p><p>When a player loses a page permission, that page&#39;s data is not cleared and the enabled page does not switch automatically. The page cannot be opened and its accessories stop contributing, but the player can recover the items with <code>retrieve</code>.</p><h2 id="permission-nodes" tabindex="-1">Permission Nodes <a class="header-anchor" href="#permission-nodes" aria-label="Permalink to “Permission Nodes”">​</a></h2><p>Permissions declared in <code>paper-plugin.yml</code> and their defaults:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>emakiaccessory.use</code></td><td><code>true</code></td><td>Open your own accessory panel, list slots and pages, and retrieve orphan slots.</td></tr><tr><td><code>emakiaccessory.reload</code></td><td><code>op</code></td><td>Reload configuration.</td></tr><tr><td><code>emakiaccessory.debug</code></td><td><code>op</code></td><td>Debug switches.</td></tr><tr><td><code>emakiaccessory.admin</code></td><td><code>op</code></td><td>Enter administrative commands.</td></tr><tr><td><code>emakiaccessory.admin.edit</code></td><td><code>op</code></td><td>Edit another player&#39;s accessories.</td></tr><tr><td><code>emakiaccessory.page.secondary</code></td><td><code>op</code></td><td>Example page permission for the default <code>secondary</code> accessory page.</td></tr></tbody></table><p>This module has <strong>no</strong> permission tiers for slot count. The number of accessory slots is decided entirely by the parts and their <code>count</code> in <code>parts.yml</code> and is unaffected by permissions.</p><p>Page permissions and command permissions are separate concerns: the <code>permission</code> field in <code>pages/*.yml</code> only decides whether a page can be opened and contributes, is used verbatim, and takes no part in command entry checks. The default resources declare a permission string only for <code>secondary</code>; custom pages choose their own.</p><h2 id="write-lease" tabindex="-1">Write Lease <a class="header-anchor" href="#write-lease" aria-label="Permalink to “Write Lease”">​</a></h2><p>Only one writable window may hold a given player&#39;s accessory data at a time. The lease is advisory: a second viewer simply fails to acquire it and gets a read-only window instead, so they can still look but every mutation is refused.</p><p>The lease is checked on the commit path rather than at render time, so a viewer who lost it can still finish reading the current screen while being unable to change anything.</p>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};